map "https://gateway-fhir-eir.labs.smartregister.org/fhir/StructureMap/unicef-mexico-child-immunization" = 'childImmunizationSchedule'

uses "http://hl7.org/fhir/StructureDefinition/Parameters" as source
uses "http://hl7.org/fhir/StructureDefinition/CarePlan" as target

group childImmunizationSchedule(source src : Parameters, target careplan: CarePlan) {
    src -> evaluate(src, $this.parameter.where(name='subject').resource) as subject,
        evaluate(src, $this.parameter.where(name='definition').resource) as definition,
        evaluate(src, $this.parameter.where(name='depends-on').resource.entry.where(resource is QuestionnaireResponse).resource) as questionnaireResponse,
        evaluate(src, $this.parameter.where(name='period').value) as period,
        evaluate(src, $this.parameter.where(name='version').value) as version
        then extractTask(period, version, subject, definition, careplan) "r_careplan";
}

group extractTask(
    source period: Period,
    source version: Integer,
    source subject : Patient,
    source definition: ActivityDefinition,
    target careplan: CarePlan) {

    // fill task into careplan contained and add reference in activity.outcome
    subject -> create('Task') as task,
        // dosage[version] does not work, hence skipping the item from given index via skip.first
        evaluate(definition, $this.dosage.skip(version).first()) as currentDose then {

        subject -> task.id = uuid(),
            task.identifier = create('Identifier') as iden, iden.value = uuid(), iden.use = 'official',
            task.status = 'requested',
            task.intent = 'plan',
            task.executionPeriod = period,
            task.priority = 'routine',
            // dosage[version] does not work, hence skipping the item from given index via skip.first
            task.description = evaluate(definition, $this.product.text + ' ' + currentDose.select(sequence.toString())),
            task.for = create('Reference') as patientReference, patientReference.reference = evaluate(subject, $this.type().name + '/' + $this.id.replaceMatches('/_history/.*', '')),
            task.basedOn = reference(careplan),
            task.authoredOn = evaluate(subject, now()),
            task.requester = evaluate(subject, $this.generalPractitioner.first()),
            task.owner = evaluate(subject, $this.generalPractitioner.first()),
            task.code = evaluate(definition, code),
            task.reasonCode = evaluate(definition, product) "r_task_data";

        subject where(currentDose.select(sequence.toString()) != '') then {
            subject -> task.description = evaluate(definition, $this.product.text + ' ' + currentDose.select(sequence.toString())) "r_task_desc_with_dose";
        } "r_task_desc_dose";

        subject where(currentDose.select(sequence.toString()) = '') then {
            subject -> task.description = evaluate(definition, $this.product.text) "r_task_desc_without_dose";
        } "r_task_desc_no_dose";

        subject then extractPeriod(subject, task) "r_task_period_extraction";

        subject -> task.reasonReference = create('Reference') as reasonReference, reasonReference.reference = 'Questionnaire/unicef-mexico-record-single-dose' "r_task_reason_reference";

        // task groupIdentifier
        subject -> task.groupIdentifier = create('Identifier') as groupIdentifier then {
            subject -> groupIdentifier.value = evaluate(definition, $this.dosage.skip(version).first().select(timing.repeat.period.toString() + '_' + timing.repeat.periodUnit)) "r_group_identifier_value";
            subject -> groupIdentifier.use = "secondary" "r_group_identifier_use";
        } "r_group_identifier";

        subject -> evaluate(task, $this.description) as desc then {
            // BCG
            subject where(desc = 'BCG') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_bcg_0";
            } "r_task_restriction_bcg_0";

            // Cholera
            subject where(desc = 'Cólera') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_cholera";
            } "r_task_restriction_cholera";

            // COVID-19
            subject where(desc = 'COVID-19 1') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_covid_1";
            } "r_task_restriction_covid_1";

            // COVID-19
            subject where(desc = 'COVID-19 2') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_covid_2";
            } "r_task_restriction_covid_2";

            // COVID-19
            subject where(desc = 'COVID-19 3') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_covid_3";
            } "r_task_restriction_covid_3";

            // DPT
            subject where(desc = 'DPT 1') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_dpt_1";
            } "r_task_restriction_dpt_1";

            // DPT
            subject where(desc = 'DPT 2') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_dpt_2";
            } "r_task_restriction_dpt_2";

            // DPT
            subject where(desc = 'DPT 3') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_dpt_3";
            } "r_task_restriction_dpt_3";

            // DPT
            subject where(desc = 'DPT 4') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_dpt_4";
            } "r_task_restriction_dpt_4";

            // DPT
            subject where(desc = 'DPT 5') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_dpt_5";
            } "r_task_restriction_dpt_5";

            // Hep-a
            subject where(desc = 'HepA 1') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hep_a_1";
            } "r_task_restriction_hep_a_1";

            // Hep-a
            subject where(desc = 'HepA 2') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hep_a_2";
            } "r_task_restriction_hep_a_2";

            // HEP B
            subject where(desc = 'HepB 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hep_b_1";
            } "r_task_restriction_hep_b_1";

            // HEP B
            subject where(desc = 'HepB 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hep_b_2";
            } "r_task_restriction_hep_b_2";

            // HEP B
            subject where(desc = 'HepB 3') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hep_b_3";
            } "r_task_restriction_hep_b_3";

            // HEP B
            subject where(desc = 'HepB 4') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hep_b_4";
            } "r_task_restriction_hep_b_4";

            // HIB
            subject where(desc = 'HIB 1') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hib_1";
            } "r_task_restriction_hib_1";

            // HIB
            subject where(desc = 'HIB 2') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hib_2";
            } "r_task_restriction_hib_2";

            // HIB
            subject where(desc = 'HIB 3') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hib_3";
            } "r_task_restriction_hib_3";

            // HIB
            subject where(desc = 'HIB 4') then {
                subject -> evaluate(subject, "365") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hib_4";
            } "r_task_restriction_hib_4";

            // HPV
            subject where(desc = 'VPH 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hpv_1";
            } "r_task_restriction_hpv_1";

            // HPV
            subject where(desc = 'VPH 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hpv_2";
            } "r_task_restriction_hpv_2";

            // HPV
            subject where(desc = 'VPH 3') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_hpv_3";
            } "r_task_restriction_hpv_3";

            // Influenza 1
            subject where(desc = 'Influenza 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_infl_1";
            } "r_task_restriction_infl_1";

            // Influenza 2
            subject where(desc = 'Influenza 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_infl_2";
            } "r_task_restriction_infl_2";

            // Influenza annual dose 1
            subject where(desc = 'Influenza A-dose 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_infl_a_1";
            } "r_task_restriction_infl_a_1";

            // Influenza annual dose 2
            subject where(desc = 'Influenza A-dose 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_infl_a_2";
            } "r_task_restriction_infl_a_2";

            // Influenza annual dose 3
            subject where(desc = 'Influenza A-dose 3') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_infl_a_3";
            } "r_task_restriction_infl_a_3";

            // Influenza annual dose 4
            subject where(desc = 'Influenza A-dose 4') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_infl_a_4";
            } "r_task_restriction_infl_a_4";

            // Measles 1
            subject where(desc = 'Sarampión 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_measles_1";
            } "r_task_restriction_measles_1";

            // Measles 2
            subject where(desc = 'Sarampión 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_measles_2";
            } "r_task_restriction_measles_2";

            // Mumps 1
            subject where(desc = 'Paperas 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_mumps_1";
            } "r_task_restriction_mumps_1";

            // Mumps 2
            subject where(desc = 'Paperas 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_mumps_2";
            } "r_task_restriction_mumps 2";

            // Pneumo 1
            subject where(desc = 'Neumonía 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_pneumo_1";
            } "r_task_restriction_pneumo_1";

            // Pneumo 2
            subject where(desc = 'Neumonía 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_pneumo_2";
            } "r_task_restriction_pneumo_2";

            // Pneumo 3
            subject where(desc = 'Neumonía 3') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_pneumo_3";
            } "r_task_restriction_pneumo_3";

            // Polio 1
            subject where(desc = 'Polio 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_polio_1";
            } "r_task_restriction_polio_1";

            // Polio 2
            subject where(desc = 'Polio 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_polio_2";
            } "r_task_restriction_polio_2";

            // Polio 3
            subject where(desc = 'Polio 3') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_polio_3";
            } "r_task_restriction_polio_3";

            // Polio 4
            subject where(desc = 'Polio 4') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_polio_4";
            } "r_task_restriction_polio_4";

            // Rota 1
            subject where(desc = 'Rota 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_rota_1";
            } "r_task_restriction_rota_1";

            // Rota 2
            subject where(desc = 'Rota 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_rota_2";
            } "r_task_restriction_rota_2";

            // Rubella 1
            subject where(desc = 'Rubéola 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_rubella_1";
            } "r_task_restriction_rubella_1";

            // Rubella 2
            subject where(desc = 'Rubéola 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_rubella_2";
            } "r_task_restriction_rubella_2";

            // Typhoid 1
            subject where(desc = 'Fiebre tifoidea 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_typhoid";
            } "r_task_restriction_typhoid";

            // Varicella 1
            subject where(desc = 'Varicela 1') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_varicella_1";
            } "r_task_restriction_varicella_1";

            // Varicella 2
            subject where(desc = 'Varicela 2') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_varicella_2";
            } "r_task_restriction_varicella_2";

            // Yellow Fever
            subject where(desc = 'Fiebre amarilla') then {
                subject -> evaluate(subject, "0") as maxDays then extractTaskRestriction(subject, task, definition, version, maxDays) "r_extract_task_restriction_yellow_fever";
            } "r_task_restriction_yellow_fever";

        } "r_task_restriction_vaccines";


        //add task.input for task dependencies
        subject -> task.input = create('Task_Input') as inputTask then {
            subject -> inputTask.type = create("CodeableConcept") as concept then {
                subject-> concept.coding = c("http://snomed.info/sct","371154000") as coding then {
                    subject -> coding.display = "Dependent (qualifier value)" "r_coding_display";
                } "r_task_concept_coding";
            } "r_codeable_concept";
            subject -> inputTask.value = 28 "r_input_value";//TODO discuss implementation on how we can make this dynamic for each dosage
        } "r_task_input";

        // dosage info
        subject -> task.input = create('Task_Input') as inputTask then {
            subject -> inputTask.type = create("CodeableConcept") as concept then {
                subject-> concept.coding = c("http://snomed.info/sct", "260911001") as coding then {
                    subject -> coding.display = "Dosage (attribute)" "r_task_input_dosage_type_coding_display";
                } "r_task_input_dosage_type_coding";
            } "r_task_input_dosage_type";
            subject -> inputTask.value = evaluate(definition, currentDose.select(sequence.toString())) "r_task_input_dosage_value";
        } "r_task_input_dosage";

        subject -> evaluate(definition, $this.product.text + ' ' + (currentDose.sequence - 1).toString()) as preReqName,
            evaluate(careplan, $this.contained.where(description.contains(preReqName))) as preReqTask then {

            subject where(preReqTask.exists()) -> task.partOf = create('Reference') as partOfReference then {
                subject -> partOfReference.reference = evaluate(preReqTask, 'Task/' + id) "r_task_reference_id";
            } "r_task_part_of";
        } "r_dosage";

        subject then extractTaskReferenceInput(subject, task, definition, version, careplan) "r_task_reference_input";

        // create activity.detail of type/kind Task for this Task if not exists
        subject where(careplan.activity.where(detail.kind = 'Task').exists().not()) -> careplan.activity = create('CarePlan_Activity') as activity then {
            subject -> activity.detail = create('CarePlan_ActivityDetail') as ActivityDefinition then {
                subject -> ActivityDefinition.kind = 'Task' "r_activity_detail_data";
            } "r_activity_detail";
        } "r_careplan_activity";

        // add task to careplan irrespective of its validity
        subject then {
            subject -> evaluate(careplan, activity.where(detail.kind = 'Task')) as activity, activity.outcomeReference = reference(task) "r_careplan_task_reference";
            subject -> careplan.contained = task "r_add_task";
        } "r_careplan_task";
    } "r_task";
}

group extractTaskReferenceInput(source subject: Patient, target task: Task, source definition: ActivityDefinition, source version: Integer, source careplan: CarePlan) {
    subject -> evaluate(task, $this.partOf.last()) as taskPartOfReference then {
        subject where(taskPartOfReference.empty().not()) then {
            subject -> task.input = create('Task_Input') as inputTask then {
                subject -> inputTask.type = create("CodeableConcept") as concept then {
                    subject-> concept.coding = c("http://snomed.info/sct","900000000000457003") as coding then {
                        subject -> coding.display = "Reference set attribute (foundation metadata concept)" "r_coding_display";
                    } "r_task_concept_coding";
                } "r_codeable_concept";
                subject -> inputTask.value = create('Reference') as partOfReference then {
                    subject -> partOfReference.reference = evaluate(subject, taskPartOfReference.reference.toString()) "r_task_reference_id";
                } "r_task_part_of_reference";
            } "r_task_input";
        } "r_task_part_of_reference_exists";
    } "r_task_part_of_reference";
}

group extractTaskRestriction(source subject: Patient, target task: Task, source definition: ActivityDefinition, source version: Integer, source restrictionEndDate: String) {
    subject -> evaluate(task, $this.executionPeriod.start) as start then {
        subject -> evaluate(subject, $this.birthDate) as patientBirthDate then {
            subject -> create("Task_Restriction") as taskRestriction then {
                subject -> taskRestriction.period = create("Period") as taskRestrictionPeriod then {
                    subject -> taskRestrictionPeriod.start = create('dateTime') as startDateTime,
                        startDateTime.value = evaluate(start, $this.value.substring(0,10) + 'T00:00:00.00Z') "r_extract_task_restriction_period_start";

                    subject -> taskRestrictionPeriod.end = create('dateTime') as endDateTime,
                        endDateTime.value = evaluate(start, (($this + (((restrictionEndDate).toString() + ' days')).toQuantity()).value.substring(0,10)) + 'T00:00:00.00Z') "r_extract_task_restriction_period_end";

                    subject -> task.restriction = taskRestriction "r_extract_task_restriction_period_restriction";
                } "r_extract_task_restriction_period";
            } "r_extract_task_restriction_task_restriction";
        } "r_extract_task_restriction_birth_date";
    } "r_extract_task_restriction";
}

group extractPeriod(source patient: Patient, target task: Task) {
    patient -> evaluate(task, $this.executionPeriod.start) as start, evaluate(task, $this.executionPeriod.end) as end then {
        patient -> create('Period') as period then {
            patient -> period.start = create('dateTime') as startDateTime,
                startDateTime.value = evaluate(start, $this.value.substring(0,10) + 'T00:00:00.00Z') "r_extract_period_executionperiod_start";

            patient -> period.end = create('dateTime') as endDateTime,
                endDateTime.value = evaluate(end, $this.value.substring(0,10) + 'T00:00:00.00Z') "r_extract_period_executionperiod_end";

            patient -> task.executionPeriod = period "r_extract_period_executionperiod";
        } "r_extract_period_period";
    } "r_extract_period";
}